using System;

namespace Bodu.Extensions;

public partial class DateTimeExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.DaysInMonth" />, when Called, returns the expected value.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(DaysInMonthTestData))]
    public void DaysInMonth_WhenCalled_ShouldReturnDaysInMonth(DateTime input, int expected)
    {
        var actual = input.DaysInMonth();
        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.DaysInMonth(DateTime, System.Globalization.CultureInfo)" /> returns
    /// the day count for the supplied culture's calendar.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCultureSupplied_ShouldReturnDaysInMonthForCulture()
    {
        var date = new DateTime(2024, 2, 15);

        Assert.AreEqual(29, date.DaysInMonth(System.Globalization.CultureInfo.InvariantCulture));
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.DaysInMonth(DateTime, System.Globalization.CultureInfo)" /> uses the
    /// current culture when the culture is <see langword="null" />.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCultureIsNull_ShouldUseCurrentCulture()
    {
        var date = new DateTime(2023, 4, 10);

        Assert.AreEqual(
            DateTime.DaysInMonth(2023, 4),
            date.DaysInMonth((System.Globalization.CultureInfo?)null));
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.DaysInMonth(DateTime, System.Globalization.Calendar)" /> returns the
    /// day count for the supplied calendar.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCalendarSupplied_ShouldReturnDaysInMonthForCalendar()
    {
        var date = new DateTime(2024, 2, 15);

        Assert.AreEqual(29, date.DaysInMonth(new System.Globalization.GregorianCalendar()));
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.DaysInMonth(DateTime, System.Globalization.Calendar)" /> uses the
    /// current culture's calendar when the calendar is <see langword="null" />.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCalendarIsNull_ShouldUseCurrentCultureCalendar()
    {
        var date = new DateTime(2023, 4, 10);

        Assert.AreEqual(
            DateTime.DaysInMonth(2023, 4),
            date.DaysInMonth((System.Globalization.Calendar?)null));
    }

    /// <summary>
    /// Verifies that a non-Gregorian calendar receives the date projected into its own year/month reckoning: for
    /// 2024-03-15 the <see cref="System.Globalization.UmAlQuraCalendar" /> month is Ramadan 1445 (30 days), whereas
    /// passing the Gregorian components (year 2024) directly would throw
    /// <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCalendarIsUmAlQura_ShouldReturnThatCalendarsMonthLength()
    {
        var calendar = new System.Globalization.UmAlQuraCalendar();
        var date = new DateTime(2024, 3, 15); // 1445-09 (Ramadan) in the Um Al-Qura calendar

        var actual = date.DaysInMonth(calendar);

        Assert.AreEqual(calendar.GetDaysInMonth(calendar.GetYear(date), calendar.GetMonth(date)), actual);
        Assert.AreEqual(30, actual);
    }

    /// <summary>
    /// Verifies that the <see cref="System.Globalization.HebrewCalendar" /> returns the length of its own month
    /// containing the date (Adar II 5784 for 2024-03-15, 29 days) rather than interpreting the Gregorian components,
    /// which lie outside the Hebrew calendar's supported year range.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCalendarIsHebrew_ShouldReturnThatCalendarsMonthLength()
    {
        var calendar = new System.Globalization.HebrewCalendar();
        var date = new DateTime(2024, 3, 15);

        var actual = date.DaysInMonth(calendar);

        Assert.AreEqual(calendar.GetDaysInMonth(calendar.GetYear(date), calendar.GetMonth(date)), actual);
        Assert.AreEqual(29, actual);
    }

    /// <summary>
    /// Verifies that a culture whose default calendar is non-Gregorian resolves the month length through that
    /// calendar's own year/month reckoning instead of the Gregorian components.
    /// </summary>
    [TestMethod]
    public void DaysInMonth_WhenCultureUsesNonGregorianCalendar_ShouldReturnThatCalendarsMonthLength()
    {
        var culture = new System.Globalization.CultureInfo("ar-SA");
        culture.DateTimeFormat.Calendar = new System.Globalization.UmAlQuraCalendar();
        var date = new DateTime(2024, 3, 15);
        var calendar = culture.DateTimeFormat.Calendar;

        var actual = date.DaysInMonth(culture);

        Assert.AreEqual(calendar.GetDaysInMonth(calendar.GetYear(date), calendar.GetMonth(date)), actual);
        Assert.AreEqual(30, actual);
    }

}
